create extension if not exists btree_gist;
alter table public.booking_requests add column if not exists idempotency_key text;
create unique index if not exists uq_booking_requests_idempotency_key on public.booking_requests(idempotency_key) where idempotency_key is not null;
create unique index if not exists uq_booking_requests_slot_hold on public.booking_requests(slot_hold_id) where slot_hold_id is not null;
alter table public.booking_requests drop constraint if exists booking_requests_no_staff_overlap;
alter table public.booking_requests add constraint booking_requests_no_staff_overlap exclude using gist (assigned_staff_id with =,tstzrange(start_at,end_at,'[)') with &&) where (assigned_staff_id is not null and status not in ('CANCELLED','FAILED','EXPIRED'));
create or replace function public.confirm_booking_slot(p_hold_id uuid,p_hold_token_hash text,p_first_name text,p_last_name text,p_phone text,p_email text,p_preferred_contact_method text,p_consent_version text,p_manage_token_hash text,p_idempotency_key text,p_optional_note text default null,p_user_id uuid default null) returns jsonb language plpgsql security definer set search_path=public as $$ declare v_hold public.booking_slot_holds%rowtype;v_booking public.booking_requests%rowtype;v_reference text;begin if coalesce(length(trim(p_idempotency_key)),0)<8 then raise exception 'invalid_idempotency_key';end if;if p_preferred_contact_method not in ('phone','sms','whatsapp','email') then raise exception 'invalid_contact_method';end if;if p_preferred_contact_method='email' and nullif(trim(coalesce(p_email,'')),'') is null then raise exception 'email_required';end if;if nullif(trim(coalesce(p_phone,'')),'') is null then raise exception 'phone_required';end if;select * into v_booking from public.booking_requests where idempotency_key=p_idempotency_key limit 1;if found then return jsonb_build_object('booking_id',v_booking.id,'public_reference',v_booking.public_reference,'status',v_booking.status,'idempotent',true);end if;select * into v_hold from public.booking_slot_holds where id=p_hold_id for update;if not found then raise exception 'hold_not_found';end if;if v_hold.hold_token_hash is distinct from p_hold_token_hash then raise exception 'invalid_hold_token';end if;select * into v_booking from public.booking_requests where slot_hold_id=p_hold_id limit 1;if found then return jsonb_build_object('booking_id',v_booking.id,'public_reference',v_booking.public_reference,'status',v_booking.status,'idempotent',true);end if;if v_hold.expires_at<=now() then raise exception 'hold_expired';end if;if v_hold.staff_id is null then raise exception 'hold_missing_staff';end if;perform pg_advisory_xact_lock(hashtext(v_hold.staff_id::text||v_hold.start_at::text));if exists(select 1 from public.booking_requests b where b.assigned_staff_id=v_hold.staff_id and b.status not in ('CANCELLED','FAILED','EXPIRED') and tstzrange(b.start_at,b.end_at,'[)')&&tstzrange(v_hold.start_at,v_hold.end_at,'[)')) then raise exception 'slot_unavailable';end if;v_reference:='LHG-'||upper(substr(replace(gen_random_uuid()::text,'-',''),1,10));insert into public.booking_requests(public_reference,user_id,booking_type_id,booked_for,first_name,last_name,phone,email,preferred_contact_method,optional_note,appointment_format,start_at,end_at,timezone,status,assigned_staff_id,consent_version,manage_token_hash,slot_hold_id,idempotency_key) values(v_reference,p_user_id,v_hold.booking_type_id,coalesce(v_hold.booked_for,'self'),trim(p_first_name),trim(p_last_name),trim(p_phone),nullif(trim(coalesce(p_email,'')),''),p_preferred_contact_method,nullif(trim(coalesce(p_optional_note,'')),''),coalesce(v_hold.appointment_format,'phone'),v_hold.start_at,v_hold.end_at,'Africa/Nairobi','CONFIRMED',v_hold.staff_id,p_consent_version,p_manage_token_hash,p_hold_id,p_idempotency_key) returning * into v_booking;insert into public.booking_events(booking_id,event_type,actor_type,actor_id,metadata) values(v_booking.id,'CONFIRMED',case when p_user_id is null then 'public' else 'user' end,p_user_id,jsonb_build_object('slot_hold_id',p_hold_id,'idempotency_key',p_idempotency_key));update public.booking_slot_holds set expires_at=now() where id=p_hold_id;return jsonb_build_object('booking_id',v_booking.id,'public_reference',v_booking.public_reference,'status',v_booking.status,'idempotent',false);exception when exclusion_violation or unique_violation then select * into v_booking from public.booking_requests where idempotency_key=p_idempotency_key or slot_hold_id=p_hold_id order by created_at asc limit 1;if found then return jsonb_build_object('booking_id',v_booking.id,'public_reference',v_booking.public_reference,'status',v_booking.status,'idempotent',true);end if;raise exception 'slot_unavailable';end;$$;
revoke all on function public.confirm_booking_slot(uuid,text,text,text,text,text,text,text,text,text,text,uuid) from public;
grant execute on function public.confirm_booking_slot(uuid,text,text,text,text,text,text,text,text,text,text,uuid) to anon,authenticated,service_role;